import {people,initialState,completeTask,addRecord,exportCsv} from './domain.mjs';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState();try{const saved=JSON.parse(localStorage.getItem('otuncares-demo-v1'));if(saved&&['tasks','logs','incidents','audit'].every(k=>Array.isArray(saved[k])))state=saved;}catch{}
let taskFilter='open',personSearch='',recordType='logs',selectedPerson='p1';
const name=id=>people.find(p=>p.id===id)?.name||'Unknown person';const stamp=()=>new Date().toLocaleString('en-GB');
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function save(){try{localStorage.setItem('otuncares-demo-v1',JSON.stringify(state));}catch{toast('Browser storage is unavailable. Changes will last only this session.');}}
function navigate(page){location.hash=page;render();}
function title(heading,sub,action=''){return `<div class="page-title"><div><span class="eyebrow">WILLOW HOUSE / DEMONSTRATION</span><h1>${heading}</h1><p>${sub}</p></div>${action}</div>`;}
function avatar(p){return `<span class="avatar" style="background:${p.colour}">${p.initials}</span>`;}
function taskRow(t){return `<div class="task"><time>${esc(t.time)}</time><div class="details"><b>${esc(t.title)}</b><p>${esc(name(t.person))} • ${esc(t.category)} <button class="quiet-btn" data-profile="${t.person}">Care plan</button></p></div>${t.done?'<span class="done">✓ Done</span>':`<button class="complete" data-complete="${t.id}">Complete</button>`}</div>`;}
function feed(r,type='logs'){return `<article class="feed-item"><div class="incident-head"><b>${esc(name(r.person))} <span class="pill ${type==='incidents'?'warning-pill':''}">${esc(r.category)}</span></b>${type==='incidents'?`<button class="filter" data-resolve="${esc(r.id)}">${r.resolved?'✓ Follow-up closed':'Close demo follow-up'}</button>`:''}</div><p>${esc(r.note)}</p><small>${esc(r.at)} • ${esc(r.author)}${r.handover?' • Handover':''}${type==='incidents'?' • '+(r.resolved?'Closed':'Open follow-up'):''}</small></article>`;}
function panel(heading,content,action=''){return `<section class="panel"><div class="panel-head"><h2>${heading}</h2>${action}</div>${content}</section>`;}
function metrics(){const done=state.tasks.filter(t=>t.done).length;return `<div class="metrics"><div class="metric"><span>People supported</span><strong>${people.length}</strong><small>All fictional demo profiles</small></div><div class="metric"><span>Open shift tasks</span><strong>${state.tasks.length-done}</strong><small>${done} of ${state.tasks.length} complete</small><div class="progress"><div style="width:${done/state.tasks.length*100}%"></div></div></div><div class="metric"><span>Care notes</span><strong>${state.logs.length}</strong><small>Recorded in this browser</small></div><div class="metric"><span>Incident follow-ups</span><strong>${state.incidents.filter(i=>!i.resolved).length}</strong><small>Open demo records</small></div></div>`;}
function dashboard(){return title('A clear start to your shift.','The people, tasks and notes that deserve your attention.',`<button class="button small" data-record="logs">＋ Record care</button>`)+metrics()+`<div class="dashboard-grid"><div>${panel('Your next steps',state.tasks.filter(t=>!t.done).map(taskRow).join('')||'<p class="empty">All shift tasks complete. Thank you.</p>','<button class="quiet-btn" data-go="tasks">View shift →</button>')}${panel('Recent care notes',state.logs.slice(0,3).map(r=>feed(r)).join('')||'<p class="empty">No care notes yet.</p>','<button class="quiet-btn" data-go="notes">All notes →</button>')}</div><div>${panel('People you’re supporting',people.map(p=>`<button class="person-row" data-profile="${p.id}">${avatar(p)}<span><b>${p.name}</b><small>${p.room} • View preferences</small></span><span>↗</span></button>`).join(''))}<div class="context-note"><b>Person first. Task second.</b><p>Before completing a task, open the person’s care plan and read what matters to them.</p></div>${panel('Keep the next shift informed',`<p class="notice">${state.logs.filter(l=>l.handover).length} care notes flagged for handover. Incident follow-ups are included separately.</p><button class="button secondary small" data-go="handover">Open handover →</button>`)}</div></div>`;}
function peoplePage(){return title('People & care plans','Start with what matters to each person.',`<input class="search" id="person-search" aria-label="Search people" placeholder="Search a person…" value="${esc(personSearch)}">`)+`<div class="person-grid">${people.filter(p=>p.name.toLowerCase().includes(personSearch.toLowerCase())).map(p=>`<button class="person-card" data-profile="${p.id}"><div class="head">${avatar(p)}<div><h2>${p.name}</h2><small>${p.room} • ${p.age} years • Fictional</small></div></div><p>“${p.preference}”</p><span class="text-link">Read preferences & plan ↗</span></button>`).join('')||'<p class="empty">No matching people.</p>'}</div>`;}
function profile(){const p=people.find(p=>p.id===selectedPerson)||people[0];return `<button class="quiet-btn" data-go="people">← All people</button><div class="profile-header">${avatar(p)}<div><h1>${p.name}</h1><p>${p.room} • ${p.age} years • Fictional demo profile</p></div></div><div class="plan-grid">${panel('What matters to me',`<div class="plan-block"><h3>My preferences</h3><p>${p.preference}</p><h3>My meaningful goal</h3><p>${p.goal}</p><h3>How to support me</h3><p>${p.support}</p><h3>Review schedule</h3><p>${p.review}</p></div><p class="notice">Illustrative care plan. No clinical instructions or live contacts.</p>`)}<div>${panel('Today’s support',state.tasks.filter(t=>t.person===p.id).map(taskRow).join('')||'<p class="empty">No tasks scheduled.</p>')}${panel('Care notes',state.logs.filter(l=>l.person===p.id).map(r=>feed(r)).join('')||'<p class="empty">No notes recorded.</p>',`<button class="quiet-btn" data-record="logs" data-person="${p.id}">＋ Add note</button>`)}</div></div>`;}
function tasks(){return title('Your shift','Review the care plan, complete support and record what you observed.',`<button class="button small" data-record="logs">＋ Record care</button>`)+`<div class="filters">${['open','complete','all'].map(f=>`<button class="filter ${f===taskFilter?'active':''}" data-filter="${f}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div>`+panel('Shift tasks',state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='complete'?t.done:!t.done)).map(taskRow).join('')||'<p class="empty">No tasks in this view.</p>');}
function notes(){return title('Daily care notes','Observations that help the next colleague understand the day.',`<button class="button small" data-record="logs">＋ Add care note</button>`)+panel('Care timeline',state.logs.map(r=>feed(r)).join('')||'<p class="empty">Record your first fictional care note.</p>');}
function incidents(){return title('Incidents & follow-up','Keep the event and its follow-up visible to your team.',`<button class="button small" data-record="incidents">＋ Record incident</button>`)+`<p class="notice">Demonstration only. Records here do not send an alert or replace your organisation’s escalation procedure.</p>`+panel('Incident records',state.incidents.map(r=>feed(r,'incidents')).join('')||'<div class="empty">No incidents recorded.<br>Use a fictional example to explore this workflow.</div>');}
function handover(){const notes=state.logs.filter(l=>l.handover);return title('A handover with context','Flagged care notes and open incident follow-ups, ready to review.',`<button class="button secondary small" id="print">Print handover</button>`)+`<div class="plan-grid">${panel('Notes for the next shift',notes.map(r=>feed(r)).join('')||'<p class="empty">No notes flagged. Select “Include in the next handover” when recording care.</p>')}${panel('Open incident follow-ups',state.incidents.filter(i=>!i.resolved).map(r=>feed(r,'incidents')).join('')||'<p class="empty">No open incident follow-ups.</p>')}</div>`;}
function reports(){return title('Your demo, in view','A simple summary of the records in this browser.',`<button class="button small" id="export">↓ Export notes CSV</button>`)+metrics()+`<div class="plan-grid">${panel('Recent demo activity',state.audit.slice(0,30).map(a=>`<div class="feed-item"><b>${esc(a.event)}</b><p>${esc(a.at)}</p></div>`).join('')||'<p class="empty">Your actions will appear here.</p>')}${panel('About these reports','<p class="notice">Activity history is local and editable through browser storage. It is not an immutable clinical audit trail.</p><p class="notice">CSV exports contain demo care notes and incidents. Tasks are summarised above.</p><button id="reset" class="button secondary small">Reset fictional demo data</button>')}</div>`;}
function readiness(){return title('What this version does','An honest starting point for Otuncares.')+`<div class="readiness-grid">${panel('Working in the web demo','<ul class="readiness-list"><li>Responsive website and care workspace</li><li>Four fictional profiles with preferences and care plans</li><li>Task completion and daily care recording</li><li>Incident follow-up and flagged handover notes</li><li>CSV export, printable handover and local persistence</li><li>Otuntech™ branding on every page</li></ul>')}${panel('Before live care use','<ul class="readiness-list"><li>Organisation accounts, verified staff roles and access controls</li><li>A shared backend, secure storage, backups and restoration</li><li>Immutable audit history and record amendments</li><li>Approved care workflows, escalation and clinical safety review</li><li>Privacy, retention and accessibility review with your care provider</li><li>Real device testing, signed native builds and store submission</li></ul>')}</div>${panel('Platform status','<p class="notice">The website is a browser demo. iOS/Android native source and Windows desktop source are supplied separately. They are not published in the Apple App Store, Google Play or Microsoft Store.</p><p class="notice">Local data does not sync between the browser, mobile and desktop apps. Do not enter real patient or service-user data. Medication administration, diagnosis, alerts and clinical risk scoring are not implemented.</p>')}`;}
function render(){const page=(location.hash.slice(1)||'dashboard').split('/')[0];const renderers={dashboard,people:peoplePage,profile,tasks,notes,handover,incidents,reports,readiness};$('#view').innerHTML=(renderers[page]||dashboard)();document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page||(page==='profile'&&b.dataset.page==='people'));if(b.classList.contains('active'))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});bind();}
function openRecord(type,person){recordType=type;$('#record-form').reset();$('#form-error').textContent='';$('#dialog-title').textContent=type==='logs'?'Record daily care':'Record an incident';$('#record-form select[name=person]').innerHTML=people.map(p=>`<option value="${p.id}">${p.name}</option>`).join('');if(person)$('#record-form select[name=person]').value=person;const cats=type==='logs'?['Wellbeing','Nutrition','Activity','Mobility','Personal care','Communication']:['Accident','Near miss','Concern','Other'];$('#record-form select[name=category]').innerHTML=cats.map(c=>`<option>${c}</option>`).join('');$('#handover-label').hidden=type!=='logs';$('#incident-notice').hidden=type!=='incidents';$('#record-dialog').showModal();}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{selectedPerson=b.dataset.profile;navigate('profile');});document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{state=completeTask(state,b.dataset.complete,stamp());save();render();toast('Demo task completed.');});document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>openRecord(b.dataset.record,b.dataset.person));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{taskFilter=b.dataset.filter;render();});document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>{const r=state.incidents.find(i=>i.id===b.dataset.resolve);if(r.resolved)return;if(!confirm('Close follow-up for this fictional incident?'))return;state={...state,incidents:state.incidents.map(i=>i.id===r.id?{...i,resolved:true}:i),audit:[{event:'Incident follow-up closed',at:stamp()},...state.audit]};save();render();toast('Demo follow-up closed.');});if($('#person-search'))$('#person-search').oninput=e=>{const pos=e.target.selectionStart;personSearch=e.target.value;render();$('#person-search').focus();$('#person-search').setSelectionRange(pos,pos);};if($('#print'))$('#print').onclick=()=>window.print();if($('#export'))$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([exportCsv(state)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='otuncares-demo-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};if($('#reset'))$('#reset').onclick=()=>{if(!confirm('Reset all local fictional demo records?'))return;state=initialState();save();render();toast('Demo reset.');};}
$('#record-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{state=addRecord(state,recordType,{id:crypto.randomUUID(),person:f.get('person'),category:f.get('category'),note:f.get('note'),handover:recordType==='logs'&&f.has('handover'),resolved:false,at:stamp(),author:'Alex Morgan (demo)'});save();$('#record-dialog').close();render();toast('Demo record saved.');}catch(err){$('#form-error').textContent=err.message;}};
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#record-dialog').close();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));window.addEventListener('hashchange',render);$('#today').textContent=new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'});render();
